<?php $versions=$versions??[];$template=$template??[]; ?>
<div class="page-header d-flex justify-content-between align-items-center mb-4"><div><div class="page-title"><?= e($template['name']) ?> — Version history</div><div class="page-subtitle mb-0">Published versions are immutable.</div></div><a class="btn btn-primary" href="<?= url('forms/templates/'.$template['slug'].'/edit') ?>">Create new version</a></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Version</th><th>Status</th><th>Change</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($versions as $v): ?><tr><td><strong>v<?= (int)$v['version_number'] ?></strong></td><td><span class="badge <?= $v['status']==='published'?'bg-success':'bg-secondary' ?>"><?= e($v['status']) ?></span></td><td><?= e($v['change_summary']??'') ?></td><td><?= e($v['created_at']??'') ?></td><td><a class="btn btn-sm btn-outline-secondary" href="<?= url('forms/templates/'.$template['slug'].'/edit?version='.(int)$v['id']) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></div>
